document.addEventListener("DOMContentLoaded",()=>{const e=[{name:"Running Stitch (Simple Kantha)",technique:"Basic running stitch",description:"The most common and fundamental Kantha stitch, used to bind layers of fabric together. It provides the characteristic wrinkled and wavy texture of Kantha textiles."},{name:"Lohori Kantha",technique:"Thick, closely set stitches",description:"Named after 'lohor' (wave), this stitch creates thick, undulating wavy patterns, often used to completely cover the fabric surface, giving it a rich texture."},{name:"Sujni Kantha",technique:"Outlined and filled",description:"Originating in Bihar and popular in Bengal, Sujni involves outlining motifs with a dark chain stitch and filling them with colorful running stitches."},{name:"Baiton Kantha",technique:"Geometric binding",description:"Used primarily for book covers or wrapping precious items. It features intricate geometric borders and a central lotus motif."}],t=[{title:"Nakshi Kantha Blanket",image:"assets/culture.png",description:"A heavily embroidered quilt used as a light blanket in winters.",context:"Traditionally crafted as a dowry gift for a daughter, encapsulating memories and blessings in every thread."},{title:"Kantha Saree",image:"assets/travel_hidden.png",description:"A pure silk or cotton saree adorned with intricate Kantha stitches.",context:"A modern evolution of the traditional Kantha, now highly valued as elegant ethnic wear in India."},{title:"Oar (Pillow Cover)",image:"assets/heritage_temples.png",description:"Small rectangular covers embroidered for pillows and cushions.",context:"Often featuring simple geometric designs or floral creepers, used in daily household decor."}],n=[{name:"Lotus (Padma)",description:"The most common central motif in a Nakshi Kantha, symbolising the universe, purity, and life's blossoming.",image:"assets/hero_banner.png"},{name:"Tree of Life",description:"A motif representing fertility, growth, and the connection between heaven, earth, and the underworld.",image:"assets/travel_mountains.png"},{name:"Kalka (Paisley)",description:"A widespread motif shaped like a teardrop or mango, used extensively in the corners and borders of Kantha.",image:"assets/heritage_forts.png"},{name:"Fish (Machh)",description:"An auspicious symbol in Bengali culture representing prosperity, fertility, and abundance.",image:"assets/travel_deserts.png"}],i=document.getElementById("details-modal"),a=document.getElementById("modal-title"),r=document.getElementById("modal-subtitle"),o=document.getElementById("modal-desc"),s=document.getElementById("close-modal");function c(e,t,n){a.textContent=e,r.textContent=t?`Details: ${t}`:"",o.textContent=n,i.classList.add("active")}s&&s.addEventListener("click",()=>{i.classList.remove("active")}),i&&i.addEventListener("click",e=>{e.target===i&&i.classList.remove("active")});const l=document.getElementById("stitch-gallery");l&&e.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.innerHTML=`\n                <div>\n                    <h3>${e.name}</h3>\n                    <p style="color: var(--text-light); font-size: 0.95rem; margin-bottom: 10px;">${e.technique}</p>\n                </div>\n                <p style="color: var(--text-muted); font-size: 0.85rem; margin-top: auto;">Click to view description</p>\n            `,t.addEventListener("click",()=>{c(e.name,e.technique,e.description)}),l.appendChild(t)});const d=document.getElementById("fabric-gallery");d&&t.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.style.cursor="default",t.innerHTML=`\n                <img src="${e.image}" alt="${e.title}" class="fabric-image" onerror="this.style.display='none'">\n                <h3>${e.title}</h3>\n                <p style="color: var(--text-light); font-size: 0.95rem; margin-bottom: 10px;">${e.description}</p>\n                <p style="color: var(--text-muted); font-size: 0.85rem; font-style: italic;">${e.context}</p>\n            `,d.appendChild(t)});const m=document.getElementById("pattern-collection");m&&n.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.innerHTML=`\n                <img src="${e.image}" alt="${e.name}" class="fabric-image" onerror="this.style.display='none'">\n                <h3>${e.name}</h3>\n                <p style="color: var(--text-muted); font-size: 0.85rem; margin-top: auto;">Click to view significance</p>\n            `,t.addEventListener("click",()=>{c(e.name,"",e.description)}),m.appendChild(t)})});